/* HYLOOKS v1.1 PRODUCTION LOADER */

const HyLooksLoader=(()=>{

const A=s=>atob(s);

const B=s=>s.split("").reverse().join("");

const C=(d,k)=>{
let o="";
for(let i=0;i<d.length;i++){
o+=String.fromCharCode(
d.charCodeAt(i)^k.charCodeAt(i%k.length)
);
}
return o;
};

function decode(video){

if(!video) return "";

const raw=A(video.encrypted);

const rev=B(raw);

return C(rev,video.iv);

}

return{decode};

})();